    {layoutMode==='advanced'&&routeWeatherSettings.enabled&&<CollapsibleModule key={`route-weather:${layoutRevision}`} id="route-weather" title="Routenwetter" summary="Schematische Strecke, Windpfeile und Einschränkungsbewertung" defaultOpen={false}><ViewportGate className="route-weather-gate" rootMargin="350px" placeholder="Routenwetter wird vorbereitet …"><Suspense fallback={<section className="lazy-placeholder inner"><RefreshCw className="spin" size={17}/><span>Routenmodul wird geladen …</span></section>}><MemoLazyRouteWeather start={loc} defaultProfile={routeWeatherSettings.defaultProfile} sampleMinutes={routeWeatherSettings.sampleMinutes}/></Suspense></ViewportGate></CollapsibleModule>}
    <CollapsibleModule key={`composite:${layoutMode}:${layoutRevision}`} id="composite" title="Kompositbild" summary="Radar, Satellit, Blitz und Modellkonturen" defaultOpen={false}><ViewportGate className="radar-gate" placeholder="Kompositbild wird geladen …"><Suspense fallback={<section className="lazy-placeholder inner"><RefreshCw className="spin" size={17}/><span>Leaflet und Komposit-Layer werden geladen …</span></section>}><MemoLazyRadar lat={loc.latitude} lon={loc.longitude} timezone={w.timezone} analysis={radarAnalysis} thunder={thunderAnalysis} isDay={Number(w.current.is_day)===1}/></Suspense></ViewportGate></CollapsibleModule>
