 const detectMountain=async(item:Favorite)=>{setMountainBusy(item.id);setMountainMessage(current=>({...current,[item.id]:'Lift- und Stationsdaten werden gesucht …'}));try{const profile=await mountainProfile(item.location);setFavorites(current=>current.map(value=>value.id===item.id?{...value,mountain:applyMountainProfile(value.location,value.mountain,profile)}:value));setMountainMessage(current=>({...current,[item.id]:`${profile.source} · ${profile.confidence==='high'?'hohe':profile.confidence==='medium'?'mittlere':'geringe'} Sicherheit`}))}catch(error){setMountainMessage(current=>({...current,[item.id]:error instanceof Error?error.message:'Automatische Bestimmung fehlgeschlagen.'}))}finally{setMountainBusy('')}};
 const patchWater=(id:string,change:Partial<WaterConfig>)=>setFavorites(current=>current.map(item=>item.id===id?{...item,water:{...item.water,...change}}:item));
 const moveTo=(sourceId:string,targetId:string)=>{if(!sourceId||sourceId===targetId)return;setFavorites(current=>{const from=current.findIndex(item=>item.id===sourceId),to=current.findIndex(item=>item.id===targetId);if(from<0||to<0||from===to)return current;const copy=[...current],[item]=copy.splice(from,1);copy.splice(to,0,item);return copy})};
