 const pointerMove=(event:ReactPointerEvent<HTMLDivElement>)=>{const active=pointerDrag.current;if(!active||active.pointerId!==event.pointerId)return;event.preventDefault();const target=document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('[data-favorite-id]')?.dataset.favoriteId;if(!target||target===active.id)return;setDragOverId(target);moveTo(active.id,target)};
