 const observed=(v:number|undefined,fallback:number)=>fresh&&Number.isFinite(v)?Number(v):fallback;
 const qffStationPressure=Boolean(st&&(st.pressureReference==='QFF'||st.pressureReference==='MSL')&&Number.isFinite(st.pressure)&&Number(st.pressure)>=870&&Number(st.pressure)<=1085),temp=observed(st?.temperature,Number(c.temperature_2m)),hum=observed(st?.humidity,Number(c.relative_humidity_2m)),dew=observed(st?.dewPoint,Number(c.dew_point_2m)),pressure=observed(qffStationPressure?st?.pressure:undefined,Number(c.pressure_msl)),windSpeed=observed(st?.windSpeed!=null?(st.windUnit==='kt'?st.windSpeed:st.windSpeed/1.852):undefined,Number(c.wind_speed_10m)),windGust=observed(st?.windGust!=null?(st.windUnit==='kt'?st.windGust:st.windGust/1.852):undefined,Number(c.wind_gusts_10m)),windDirection=observed(st?.windDirection,Number(c.wind_direction_10m)),cloud=observed(st?.cloudCover,Number(c.cloud_cover)),cloudOktasValue=cloudOktas(cloud),ceilingHft=fresh&&Number.isFinite(st?.ceilingHft)?Math.round(Number(st?.ceilingHft)):Number.NaN,cloudBaseHft=fresh&&Number.isFinite(st?.cloudBaseHft)?Math.round(Number(st?.cloudBaseHft)):Number.NaN,cloudBaseDetail=cloudOktasValue>=5&&Number.isFinite(ceilingHft)?`Ceiling ${ceilingHft} hft · `:cloudOktasValue>=1&&cloudOktasValue<=4&&Number.isFinite(cloudBaseHft)?`Wolkenuntergrenze ${cloudBaseHft} hft · `:'',precip=observed(st?.precipitation,Number(c.precipitation)),visibility=observed(st?.visibility,Number(c.visibility));
 const mappedHours=hours,mappedDays=days,todayDate=localDateInZone(w.timezone),currentDay=mappedDays.find(day=>day.date===todayDate)??mappedDays[0],pressureChange=pressureTendency(mappedHours),astronomy=astronomySummary(w),currentPrecip=precipitationParts({precipitation:precip,rain:Number(c.rain)||0,showers:Number(c.showers)||0,snowfall:Number(c.snowfall)||0,probability:0,code:Number(c.weather_code)||0,temperature:temp,dewPoint:dew,humidity:hum,cloud,lowCloud:Number(c.cloud_cover_low),cloudBaseHft:Number.isFinite(cloudBaseHft)?cloudBaseHft:undefined,ceilingHft:Number.isFinite(ceilingHft)?ceilingHft:undefined}),currentWeatherCode=currentPrecip.displayCode,currentWeatherLabel=currentPrecip.type==='none'?label(currentWeatherCode):currentPrecip.weatherLabel;
