 const timed=samples.map(x=>({...x,ts:Number.isFinite(x.epoch)?Number(x.epoch):Date.parse(`${String(x.time)}Z`)})).filter(x=>Number.isFinite(x.ts)).sort((a,b)=>a.ts-b.ts);
