type WidgetStoredSettings={days:number;dark:boolean;showWind:boolean;showRain:boolean;showHazards:boolean};
const WIDGET_SETTINGS_STORAGE_KEY='mid:0.7.1:widget-settings';
function storedWidgetSettings():WidgetStoredSettings{const defaults={days:4,dark:true,showWind:true,showRain:true,showHazards:true};try{const parsed=JSON.parse(localStorage.getItem(WIDGET_SETTINGS_STORAGE_KEY)||'{}') as Partial<WidgetStoredSettings>,days=Number(parsed.days);return{days:[3,4,5,6,7].includes(days)?days:defaults.days,dark:typeof parsed.dark==='boolean'?parsed.dark:defaults.dark,showWind:typeof parsed.showWind==='boolean'?parsed.showWind:defaults.showWind,showRain:typeof parsed.showRain==='boolean'?parsed.showRain:defaults.showRain,showHazards:typeof parsed.showHazards==='boolean'?parsed.showHazards:defaults.showHazards}}catch{return defaults}}
function Widget({loc,days,hours,unit,elevation,timezone,timezoneAbbreviation}:{loc:Location;days:Day[];hours:Hour[];unit:WindUnit;elevation?:number;timezone:string;timezoneAbbreviation?:string}){
 const initial=useMemo(storedWidgetSettings,[]),[n,setN]=useState(initial.days),[dark,setDark]=useState(initial.dark),[showWind,setShowWind]=useState(initial.showWind),[showRain,setShowRain]=useState(initial.showRain),[showHazards,setShowHazards]=useState(initial.showHazards),[copyState,setCopyState]=useState<'idle'|'working'|'done'|'fallback'|'error'>('idle'),[copyImage,setCopyImage]=useState(''),ref=useRef<HTMLDivElement>(null);
 useEffect(()=>{try{localStorage.setItem(WIDGET_SETTINGS_STORAGE_KEY,JSON.stringify({days:n,dark,showWind,showRain,showHazards} satisfies WidgetStoredSettings))}catch{}},[n,dark,showWind,showRain,showHazards]);
 useEffect(()=>()=>{if(copyImage)URL.revokeObjectURL(copyImage)},[copyImage]);
 const previewDays=useMemo(()=>days.slice(0,n).map(d=>{const dayHours=hours.filter(x=>x.time.startsWith(d.date));return{...d,hz:dailyHazards(d,hours,elevation??0,unit,1),character:dayWeatherCharacter(d,dayHours)}}),[days,hours,n,elevation,unit]),widgetWidth=Math.max(360,112+n*82);
 async function renderWidgetBlob(){if(!ref.current)return null;const{toBlob}=await import('html-to-image');return toBlob(ref.current,{pixelRatio:2,cacheBust:true,backgroundColor:dark?'#07111f':'#f7fbff',width:ref.current.scrollWidth,height:ref.current.scrollHeight})}
 function exposeForCopy(blob:Blob){setCopyImage(current=>{if(current)URL.revokeObjectURL(current);return URL.createObjectURL(blob)});setCopyState('fallback')}
 async function copyForPowerPoint(){if(!ref.current)return;setCopyState('working');let blob:Blob|null=null;try{blob=await renderWidgetBlob();if(!blob)throw new Error('Bild konnte nicht erzeugt werden.');const ClipboardItemCtor=(window as any).ClipboardItem;if(!navigator.clipboard?.write||!ClipboardItemCtor){exposeForCopy(blob);return}await navigator.clipboard.write([new ClipboardItemCtor({'image/png':blob})]);setCopyState('done');setTimeout(()=>setCopyState(current=>current==='done'?'idle':current),2600)}catch{if(blob)exposeForCopy(blob);else setCopyState('error')}}
 async function png(){const blob=await renderWidgetBlob();if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.download=`wetter-widget-${loc.name.toLowerCase().replace(/[^a-z0-9]+/gi,'-')}-${n}tage.png`;a.href=url;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
 const copyCaption=copyState==='working'?'Widget wird gerendert …':copyState==='done'?'In Zwischenablage · jetzt in der Zielanwendung einfügen':copyState==='fallback'?'Browser blockiert Direktkopie · Bild unten per Rechtsklick kopieren':copyState==='error'?'Export konnte nicht erstellt werden.':'PNG direkt in die Zwischenablage kopieren';
 return <section className="card widget widget-embedded"><div className="widgetlayout"><aside className="widget-controls"><label>Tage<select value={n} onChange={e=>setN(Number(e.target.value))}>{[3,4,5,6,7].map(x=><option key={x}>{x}</option>)}</select></label><label><input type="checkbox" checked={dark} onChange={e=>setDark(e.target.checked)}/>Dunkles Widget</label><label><input type="checkbox" checked={showWind} onChange={e=>setShowWind(e.target.checked)}/>Wind</label><label><input type="checkbox" checked={showRain} onChange={e=>setShowRain(e.target.checked)}/>Niederschlag</label><label><input type="checkbox" checked={showHazards} onChange={e=>setShowHazards(e.target.checked)}/>Hazards anzeigen</label><small>Die Ausgabe passt sich automatisch an. „in Zwischenablage kopieren“ legt ein hochauflösendes PNG in die Zwischenablage; anschließend genügt Einfügen in PowerPoint oder eine andere Anwendung.</small><div className="widget-export-actions"><button className="primary" disabled={copyState==='working'} onClick={()=>void copyForPowerPoint()}><ClipboardCopy size={17}/>{copyState==='working'?'Wird kopiert …':'in Zwischenablage kopieren'}</button><button className="secondary" onClick={()=>void png()}><Download size={17}/>PNG herunterladen</button></div><small className={`widget-copy-status ${copyState}`}>{copyCaption}</small>{copyImage&&copyState==='fallback'&&<div className="widget-copy-fallback"><img src={copyImage} alt="Gerendertes MID-Widget zum Kopieren"/><small>Rechtsklick beziehungsweise langes Drücken auf das Bild → „Bild kopieren“, danach in PowerPoint einfügen.</small></div>}</aside><div className="preview widget-preview"><div ref={ref} style={{width:`${widgetWidth}px`}} className={`weatherwidget modern compact ${dark?'dark':'light'} ${showHazards?'hazards-on':'hazards-off'}`}><header><div><span>MID Widget</span><strong>{loc.name}</strong><small>{formatDecimal(loc.latitude,2,2)}°N, {formatDecimal(loc.longitude,2,2)}°E · {Math.round(elevation??0)} m ü. NHN · Ortszeit {timezoneAbbreviation||timezone}</small></div><b>{n}-Tage-Ausblick</b></header><div className={`widgetgrid days-${n}`}>{previewDays.map(d=><article key={d.date} className="widgetday"><div className="widgetday-head"><strong>{formatDateOnly(d.date,{weekday:'short'})}</strong><small>{formatDateOnly(d.date,{day:'2-digit',month:'2-digit'})}</small></div><div className="widgeticon">{icon(d.character.code)}</div><b className="widgetlabel">{d.character.label}</b><div className="widgettemps"><strong>{Math.round(d.max)}°</strong><em>{Math.round(d.min)}°</em></div><div className="widgetmeta">{showRain&&<span>💧 {formatDecimalFixed(d.precipitation,1)} mm · {Math.round(d.probability)} %</span>}{showWind&&<span>🌬️ <WindDirectionArrow direction={d.direction}/> {wind(d.wind,unit)} · Böen {wind(d.gust,unit)}</span>}</div>{showHazards&&<div className="widgethazards">{d.hz.length?d.hz.map((h,i)=><span key={i} className={h.level} title={`${h.title}: ${h.detail}`}>{h.symbol}{h.value?` ${h.value}`:''}</span>):<span className="ok">keine Hazards</span>}</div>}</article>)}</div><footer><span>Open-Meteo · MID v{VERSION}</span><span>{formatInZone(new Date(),timezone,{day:'2-digit',month:'2-digit',year:'numeric'})}</span></footer></div></div></div></section>
}
function formatModelRunTime(value?:string){if(!value)return'–';const d=new Date(value);return Number.isFinite(d.getTime())?`${d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',timeZone:'UTC'})} ${String(d.getUTCHours()).padStart(2,'0')}Z`:'–'}
function formatAvailabilityTime(value?:string){if(!value)return'–';const d=new Date(value);if(!Number.isFinite(d.getTime()))return'–';const recent=Date.now()-d.getTime()<18*3600000;return recent?`${String(d.getUTCHours()).padStart(2,'0')}:${String(d.getUTCMinutes()).padStart(2,'0')}Z`:`${d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',timeZone:'UTC'})} ${String(d.getUTCHours()).padStart(2,'0')}:${String(d.getUTCMinutes()).padStart(2,'0')}Z`}
function ModelRunDetails({kind,info,runs=[]}:{kind:'best'|'ensemble';info?:BestMatchModelInfo|null;runs?:ModelRunMeta[]}){
 const rows=kind==='best'?(info?.runs??[]):runs,buttonRef=useRef<HTMLButtonElement>(null),[open,setOpen]=useState(false);
 return <span className="model-run-details"><button ref={buttonRef} type="button" className="model-run-button" title="Modellläufe und Datenstand anzeigen" aria-label="Modellstände anzeigen" aria-expanded={open} onClick={event=>{event.preventDefault();event.stopPropagation();setOpen(value=>!value)}}>ⓘ Modellstände</button><PortalPopover anchorRef={buttonRef} open={open} onClose={()=>setOpen(false)} className="model-run-popover" width={420}>{kind==='best'?<><strong>Best Match</strong><p>{info?.summary??'Modellinformationen werden geladen …'}</p>{info?.likelyChain&&<p className="model-run-chain"><b>Wahrscheinliche Kette:</b> {info.likelyChain}</p>}</>:<><strong>Aktive Ensemble-Modelle</strong><p>Initialisierung und Verfügbarkeitszeit der tatsächlich erfolgreich eingebundenen Modelle.</p></>}{rows.length?<div className="model-run-list">{rows.map(row=><div className="model-run-row" key={`${row.kind}:${row.id}`}><span>{row.label}</span><small>Initialisierung {formatModelRunTime(row.initialisationTime)} · verfügbar seit {formatAvailabilityTime(row.availabilityTime)}</small></div>)}</div>:<small className="model-run-empty">Modellstände werden geladen oder sind derzeit nicht verfügbar.</small>}</PortalPopover></span>
}
function Title({eye,title,children}:{eye:string;title:string;children?:ReactNode}){return <header className="title"><div><span>{eye}</span><h2>{title}</h2></div>{children&&<div className="title-tools">{children}</div>}</header>}
